<script setup>import {onMounted,ref,onUnmounted} from 'vue';import client from '@/api/client';const board=ref({}),error=ref('');async function load(){try{board.value=(await client.get('/work-orders/board')).data.data}catch(e){error.value='Papan gagal dimuat.'}}let timer;onMounted(()=>{load();timer=setInterval(load,10000)});onUnmounted(()=>clearInterval(timer))</script><template><main><h1 class="h4">Papan Antrian</h1><div v-if="error" class="alert alert-danger">{{error}}</div><div class="row g-3"><section v-for="(items,status) in board" :key="status" class="col-md-3"><h2 class="h6 text-capitalize">{{status}}</h2><RouterLink v-for="item in items" :key="item.id" :to="`/work-orders/${item.id}`" class="card mb-2 p-3 text-decoration-none">{{item.queue_number_display}}</RouterLink><p v-if="!items?.length" class="text-muted">Kosong</p></section></div></main></template>